;; curriculum: Precalc / Calc-1 (gr 11–12) — secant to tangent; prerequisites: limits, deriv
;; math target: as two points squeeze together, the secant slope approaches the tangent slope: Δx → 0.

app riya-level-secant "1.1.0"
"riya level 18 · The Secant — y = x² ⁄ 16 — the secant line between Riya and a beacon closes in until it becomes the tangent. Catch 5 ★! Composed from std-platformer-body + std-objective-flow + std-fx-particles + std-pickup + std-tutorial-overlay, rendered through math-canvas so the curve, secant, tangent and slope readout carry the lesson. Rebound into the riya-game-platformer organism (menu + all worlds)."

;; @exposure internal

orbital RiyaSecantOrbital {
  uses Body from "std/behaviors/std-platformer-body"
  uses Gate from "std/behaviors/std-objective-flow"
  uses Particles from "std/behaviors/std-fx-particles"
  uses Pickup from "std/behaviors/std-pickup"
  uses Tutorial from "std/behaviors/std-tutorial-overlay"
  uses Genre from "std/behaviors/std-platformer-puzzle"

  type RiyaSecantBody = {
    x : number!
    y : number!
    width : number!
    height : number!
    vx : number
    vy : number
    grounded : boolean
    facingRight : boolean
  }
  type RiyaSecantPlatform = {
    id : string
    x : number!
    y : number!
    width : number!
    height : number!
    type : "ground" | "platform" | "hazard" | "goal"
  }
  type RiyaSecantFx = {
    id : string!
    type : string!
    x : number!
    z : number
    y : number
    message : string
    ttl : number!
    maxTtl : number
    bornAt : number
    space : string
    effect : string
    color : string
    size : number
    vx : number
    vy : number
    vz : number
    particleCount : number
    animation : string
  }
  type RiyaSecantFxPreset = {
    type : string!
    color : string
    color2 : string
    size : number
    shape : string
    count : number
    glow : number
    vy : number
    animation : string
  }
  type RiyaSecantStar = {
    id : string!
    x : number!
    y : number!
    type : string!
  }
  type RiyaSecantCurveSample = {
    x : number!
    y : number!
  }
  type RiyaSecantCurve = {
    label : string
    color : string
    samples : [RiyaSecantCurveSample]!
    dash : "dashed" | "dotted"
  }
  type RiyaSecantGuide = {
    kind : "vline" | "hline"!
    at : number!
    color : string
    dash : "dashed" | "dotted"
    label : string
  }
  type RiyaSecantPickup = {
    id : string!
    x : number!
    y : number!
    kind : string!
    glyph : string
    message : string
    collected : boolean
  }

  entity RiyaSecantState [runtime, shared] {
    id : string!
    active : boolean = false
    body : RiyaSecantBody = { x: -6, y: 2.65, width: 0.6, height: 0.6, vx: 0, vy: 0, grounded: false, facingRight: true }
    fell : boolean = false
    hazardId : string = ""
    goalId : string = ""
    skating : boolean = false
    features : [RiyaSecantStar] = []
    pickups : [RiyaSecantPickup] = []
    pickupCompleted : boolean = false
    total : number = 0
    score : number = 0
    objectivesLeft : number = 0
    result : string = "none"
    fx : [RiyaSecantFx] = []
    celebrated : boolean = false
    seq : number = 0
    lastText : string = ""
    zoneId : string = "secant"
    platforms : [RiyaSecantPlatform] = []
    curves : [RiyaSecantCurve] = []
  }

  entity SecantTutorialData [runtime] {
    id : string!
    step : number = 0
    done : boolean = false
  }

  trait SecantBody = Body.traits.PlatformerBody -> RiyaSecantState {
    events {
      STEER: SECANT_STEER
      JUMP: SECANT_LEAP
      PLACE: SECANT_PLACE
      RESTART: SECANT_RESTART
      BODY_JUMPED: SECANT_JUMPED
      BODY_LANDED: SECANT_LANDED
      BODY_HAZARD: SECANT_HAZARD
      BODY_GOAL: SECANT_GOAL
      BODY_FELL: SECANT_FELL
      BODY_SKATE_START: SECANT_SKATE_ON
      BODY_SKATE_END: SECANT_SKATE_OFF
      SET_PLATFORMS: SECANT_SET_PLATFORMS
      SET_SKATE_CURVE: SECANT_SET_SKATE_CURVE
    }
    config {
      running: true
      spawn: { x: -6, y: 2.65, width: 0.6, height: 0.6, vx: 0, vy: 0, grounded: false, facingRight: true }
      gravity: -24
      jumpStrength: 11
      moveSpeed: 5
      maxFallSpeed: 14
      xMin: -10
      xMax: 9.4
      killY: -3
      skate: true
      curveModsEnabled: false
      skateSnap: 0.9
    }
  }

  trait SecantGate = Gate.traits.ObjectiveFlow -> RiyaSecantState {
    events {
      PROGRESS: SECANT_PROGRESS
      GAME_END: SECANT_GAME_END
      RESTART: SECANT_RESTART
    }
    config { running: true }
  }

  trait SecantFx = Particles.traits.FxParticles -> RiyaSecantState {
    events {
      BURST: SECANT_BURST
    }
    config { running: true }
  }

  trait SecantLevelData -> @rebindable RiyaSecantState [lifecycle] {
    initial: active

    state active {
      INIT -> active
        (emit RIYA_LEVEL_DATA {
          id: "secant"
          name: @config.worldName
          equation: @config.equation
          concept: @config.concept
          regionColor: @config.regionColor
          entryY: @config.entryY
          exitY: @config.exitY
          platforms: (array/map @config.platforms (fn p @p))
          stars: (array/map @config.stars (fn s @s))
          curveOverlay: (array/map @config.curveOverlay (fn c @c))
          skateCurve: (array/map @config.skateCurve (fn s @s))
        })
    }

    emits {
      RIYA_LEVEL_DATA -> external {
        id : string!
        name : string!
        equation : string!
        concept : string!
        regionColor : string!
        entryY : number!
