      skateCurve : [RiyaSecantCurveSample] = [ { x: -8, y: 4 }, { x: -7, y: 3.06 }, { x: -6, y: 2.25 }, { x: -5, y: 1.56 }, { x: -4, y: 1 }, { x: -3, y: 0.56 }, { x: -2, y: 0.25 }, { x: -1, y: 0.06 }, { x: 0, y: 0 }, { x: 1, y: 0.06 }, { x: 2, y: 0.25 }, { x: 3, y: 0.56 }, { x: 4, y: 1 }, { x: 5, y: 1.56 }, { x: 6, y: 2.25 }, { x: 7, y: 3.06 }, { x: 8, y: 4 } ]
