  trait RiyaSecantPlay -> @rebindable RiyaSecantState [interaction, instance] {
    initial: idle

    state idle {
      INIT -> idle
        (set @entity.active true)
        (set @entity.celebrated false)
        (set @entity.score 0)
        (emit SECANT_RESTART { id: "board" })
        (let ((beaconX (math/max @config.beaconTargetX (- @config.beaconStartX (* (+ @entity.body.x 6) (/ (- @config.beaconStartX @config.beaconTargetX) (- @config.beaconSlideEndX @config.beaconSlideStartX)))))))
        (let ((beaconY (/ (* @beaconX @beaconX) 16)))
        (let ((riyaX (+ @entity.body.x 0.3)))
        (let ((riyaY (+ @entity.body.y 0.3)))
        (let ((secantSlope (if (> (math/abs (- @beaconX @riyaX)) 0.01) (/ (- @beaconY @riyaY) (- @beaconX @riyaX)) 0)))
        (let ((tangentSlope (/ @config.beaconTargetX 8)))
        (render-ui main {
          type: game-shell
          appName: (str/concat "riya · " @config.worldName)
          fontFamily: "future-narrow"
          children: [ {
            type: math-canvas
            width: @config.width
            height: @config.height
            xMin: @config.xMin
            xMax: @config.xMax
            yMin: @config.yMin
            yMax: @config.yMax
            showTickLabels: true
            showCurveLabels: true
            keyMap: { ArrowLeft: "SECANT_LEFT", KeyA: "SECANT_LEFT", ArrowRight: "SECANT_RIGHT", KeyD: "SECANT_RIGHT", ArrowUp: "SECANT_JUMP", KeyW: "SECANT_JUMP", Space: "SECANT_JUMP" }
            keyUpMap: { ArrowLeft: "SECANT_STOP", KeyA: "SECANT_STOP", ArrowRight: "SECANT_STOP", KeyD: "SECANT_STOP" }
            curves: (array/concat
              (array/map @entity.curves (fn c (object/merge @c { color: (if @entity.skating @config.curveSkateColor (object/get @c color)) })))
              [ @config.ghostCurve, @config.tangentCurve ])
            bars: (array/map @entity.platforms (fn p { x: (object/get @p x), width: (object/get @p width), y0: (object/get @p y), y1: (+ (object/get @p y) (object/get @p height)), color: @config.terrainColor, opacity: 0.85 }))
            points: (array/concat
              (array/map (array/filter @entity.pickups (fn p (== (object/get @p collected) false))) (fn f { x: (object/get @f x), y: (object/get @f y), label: (object/get @f glyph), color: (if (== (object/get @f kind) "star") @config.starColor "#f472b6"), radius: 9 }))
              [ { x: @riyaX, y: @riyaY, label: "riya", color: @config.riyaColor, radius: 6 }, { x: @beaconX, y: @beaconY, label: "beacon", color: "#facc15", radius: 8 } ])
            drawables: [ {
              type: "draw-fx-layer"
              items: @entity.fx
              tickMs: 500
              presets: @config.fxPresets
            } ]
            vectors: [
              { x: @riyaX, y: (+ @entity.body.y @config.arrowOffsetY), vx: (* @entity.body.vx @config.arrowScale), vy: (* @entity.body.vy @config.arrowScale), color: @config.riyaColor, label: "v" }
              { x: @riyaX, y: @riyaY, vx: (- @beaconX @riyaX), vy: (- @beaconY @riyaY), color: "#f472b6", label: "secant" }
            ]
          } ]
        })))))))
        (render-ui hud-top {
          type: stack
          direction: horizontal
          justify: center
          className: "p-3"
          children: [ { type: game-hud, variant: "floating", stats: [ { label: "★", value: @entity.score } ] } ]
        })
        (render-ui hud-bottom {
          type: stack
          direction: horizontal
          justify: start
          className: "p-4"
          children: [ { type: control-grid, kind: "dpad", visibility: "auto", directionEvents: { left: "SECANT_LEFT", right: "SECANT_RIGHT", up: "SECANT_JUMP" }, directionReleaseEvents: { left: "SECANT_STOP", right: "SECANT_STOP" } } ]
        })

      RIYA_LEVEL_DATA -> idle when (== @payload.id "secant")
        (set @entity.curves @payload.curveOverlay)
        (set @entity.objectivesLeft (array/len @payload.stars))
        (emit SECANT_SET_PLATFORMS { platforms: @payload.platforms })
        (emit SECANT_SET_SKATE_CURVE { curve: @payload.skateCurve })
        (emit SECANT_SET_FEATURES { features: @payload.stars })

      SECANT_LEFT -> idle when (and (== @entity.active true) (== @entity.result "none"))
        (emit SECANT_STEER { dir: -1 })

      SECANT_RIGHT -> idle when (and (== @entity.active true) (== @entity.result "none"))
        (emit SECANT_STEER { dir: 1 })

      SECANT_STOP -> idle when (== @entity.active true)
        (emit SECANT_STEER { dir: 0 })

      SECANT_JUMP -> idle when (and (== @entity.active true) (== @entity.result "none"))
        (emit SECANT_LEAP {})

      SECANT_FELL -> idle when (== @entity.active true)
        (emit SECANT_PLACE { x: @config.respawnX, y: @config.respawnY })
        (emit SECANT_BURST { particles: (array/map [ "fx-secant-fell" ] (fn fid { id: @fid, type: "info", x: @config.respawnX, z: @config.respawnY, message: "💫", ttl: 3, maxTtl: 3, bornAt: (time/now), space: "world", effect: "float-text", color: "#a78bfa", size: 0.8, vx: 0, vy: 0, vz: 0, particleCount: 1, animation: "" })) })

      SECANT_SKATE_ON -> idle when (== @entity.active true)
        (emit SECANT_BURST { particles: (array/concat
          (array/map [ "skate" ] (fn _ { id: "narrative-skate", type: "narrative", x: @entity.body.x, z: (+ @entity.body.y 2), y: 0, message: "average rate of change", ttl: 2, maxTtl: 2, bornAt: (time/now), space: "world", effect: "float-text", color: "#a78bfa", size: 0.6, vx: 0, vy: 0, vz: 0, particleCount: 1 }))
          (array/map [ "fx-secant-skate" ] (fn fid { id: @fid, type: "info", x: @payload.x, z: (+ @payload.y 0.6), message: (str/concat "m ≈ " (math/round @payload.slope 2)), ttl: 4, maxTtl: 4, bornAt: (time/now), space: "world", effect: "float-text", color: "#38bdf8", size: 0.6, vx: 0, vy: 0, vz: 0, particleCount: 1, animation: "" }))
        ) })
      SECANT_PICKED -> idle when (== @entity.active true)
        (emit SECANT_BURST { particles: (array/map [ "fx-pickup-" ] (fn fid { id: (str/concat @fid @payload.id), type: "pickup", x: @payload.x, z: @payload.y, message: (if (== @payload.kind "star") @payload.glyph @payload.message), ttl: 2, maxTtl: 2, bornAt: (time/now), space: "world", effect: "float-text", color: "#f472b6", size: 0.8, vx: 0, vy: 0, vz: 0, particleCount: 1, animation: "" })) })
      SECANT_COLLECT -> idle when (== @entity.active true)
        (set @entity.score @payload.total)
        (set @entity.objectivesLeft (- (array/len @entity.pickups) @payload.total))
        (emit SECANT_PROGRESS { objectivesLeft: @entity.objectivesLeft, movesLeft: 9999 })
        (render-ui hud-top {
          type: stack
          direction: horizontal
          justify: center
          className: "p-3"
          children: [ { type: game-hud, variant: "floating", stats: [ { label: "★", value: @entity.score } ] } ]
        })

      SECANT_PICKUP_SET_COMPLETED -> idle when (== @entity.active true)
        (emit SECANT_BURST { particles: (array/map [ "complete" ] (fn _ { id: "narrative-complete", type: "narrative", x: 5, z: 4, y: 0, message: "secant slope → tangent slope as Δx → 0", ttl: 3, maxTtl: 3, bornAt: (time/now), space: "world", effect: "float-text", color: "#facc15", size: 0.9, vx: 0, vy: 0, vz: 0, particleCount: 1 })) })
        (emit SECANT_PROGRESS { objectivesLeft: 0, movesLeft: 9999 })
      SECANT_GAME_END -> idle when (and (== @payload.result "won") (== @entity.celebrated false))
        (set @entity.celebrated true)
        (emit RIYA_LEVEL_SOLVED { level: "secant" })

      SECANT_TUTORIAL_DONE -> idle
        (emit SECANT_BURST { particles: (array/map [ "tutorial" ] (fn _ { id: "narrative-tutorial", type: "narrative", x: 5, z: 4, y: 0, message: "secant slope = Δy/Δx", ttl: 3, maxTtl: 3, bornAt: (time/now), space: "world", effect: "float-text", color: "#38bdf8", size: 0.9, vx: 0, vy: 0, vz: 0, particleCount: 1 })) })
    }

    ticks {
      renderTick every 100ms when (== @entity.active true)
        (let ((beaconX (math/max @config.beaconTargetX (- @config.beaconStartX (* (+ @entity.body.x 6) (/ (- @config.beaconStartX @config.beaconTargetX) (- @config.beaconSlideEndX @config.beaconSlideStartX)))))))
        (let ((beaconY (/ (* @beaconX @beaconX) 16)))
        (let ((riyaX (+ @entity.body.x 0.3)))
        (let ((riyaY (+ @entity.body.y 0.3)))
        (let ((secantSlope (if (> (math/abs (- @beaconX @riyaX)) 0.01) (/ (- @beaconY @riyaY) (- @beaconX @riyaX)) 0)))
        (let ((tangentSlope (/ @config.beaconTargetX 8)))
        (render-ui main {
          type: game-shell
          appName: (str/concat "riya · " @config.worldName)
          fontFamily: "future-narrow"
          children: [ {
            type: math-canvas
            width: @config.width
            height: @config.height
            xMin: @config.xMin
            xMax: @config.xMax
            yMin: @config.yMin
            yMax: @config.yMax
            showTickLabels: true
            showCurveLabels: true
            keyMap: { ArrowLeft: "SECANT_LEFT", KeyA: "SECANT_LEFT", ArrowRight: "SECANT_RIGHT", KeyD: "SECANT_RIGHT", ArrowUp: "SECANT_JUMP", KeyW: "SECANT_JUMP", Space: "SECANT_JUMP" }
            keyUpMap: { ArrowLeft: "SECANT_STOP", KeyA: "SECANT_STOP", ArrowRight: "SECANT_STOP", KeyD: "SECANT_STOP" }
            curves: (array/concat
              (array/map @entity.curves (fn c (object/merge @c { color: (if @entity.skating @config.curveSkateColor (object/get @c color)) })))
              [ @config.ghostCurve, @config.tangentCurve ])
            bars: (array/map @entity.platforms (fn p { x: (object/get @p x), width: (object/get @p width), y0: (object/get @p y), y1: (+ (object/get @p y) (object/get @p height)), color: @config.terrainColor, opacity: 0.85 }))
            points: (array/concat
              (array/map (array/filter @entity.pickups (fn p (== (object/get @p collected) false))) (fn f { x: (object/get @f x), y: (object/get @f y), label: (object/get @f glyph), color: (if (== (object/get @f kind) "star") @config.starColor "#f472b6"), radius: 9 }))
              [ { x: @riyaX, y: @riyaY, label: "riya", color: @config.riyaColor, radius: 6 }, { x: @beaconX, y: @beaconY, label: "beacon", color: "#facc15", radius: 8 } ])
            drawables: [ {
              type: "draw-fx-layer"
              items: @entity.fx
              tickMs: 500
              presets: @config.fxPresets
            } ]
            vectors: [
              { x: @riyaX, y: (+ @entity.body.y @config.arrowOffsetY), vx: (* @entity.body.vx @config.arrowScale), vy: (* @entity.body.vy @config.arrowScale), color: @config.riyaColor, label: "v" }
              { x: @riyaX, y: @riyaY, vx: (- @beaconX @riyaX), vy: (- @beaconY @riyaY), color: "#f472b6", label: "secant" }
            ]
          } ]
        })))))))
    }

    emits {
      SECANT_LEFT -> external {
        id : string
      }
        @description "Run-left intent from ArrowLeft/KeyA keydown or d-pad (forwarded as STEER dir −1)."
        @tier "domain"
      SECANT_RIGHT -> external {
        id : string
      }
        @description "Run-right intent from ArrowRight/KeyD keydown or d-pad (forwarded as STEER dir +1)."
        @tier "domain"
      SECANT_STOP -> external {
        id : string
      }
        @description "Left/right key release (keyUpMap or d-pad release); forwarded as STEER dir 0."
        @tier "domain"
      SECANT_JUMP -> external {
        id : string
      }
        @description "Jump intent from Space/ArrowUp/KeyW or d-pad up; forwarded as the body authority's renamed JUMP (SECANT_LEAP), which accepts it only while grounded."
        @tier "domain"
      SECANT_STEER -> external {
        dir : number!
      }
        @description "Renamed STEER consumed by this world's platformer-body authority (−1/0/+1 × moveSpeed)."
        @tier "domain"
      SECANT_LEAP -> external {
        id : string
      }
        @description "Renamed JUMP consumed by this world's platformer-body authority (grounded-gated vertical kick)."
        @tier "domain"
      SECANT_PLACE -> external {
        x : number!
        y : number!
      }
        @description "Renamed PLACE consumed by this world's platformer-body authority; the pit-fall respawn teleport."
        @tier "domain"
      SECANT_FELL -> external {
        x : number!
        y : number!
      }
        @description "Pit-fall signal from this world's platformer-body authority (renamed BODY_FELL); respawns riya at her spawn with every star kept."
        @tier "domain"
      SECANT_SKATE_ON -> external {
        x : number!
        y : number!
        slope : number!
      }
        @description "Skate-engage signal from this world's platformer-body authority (renamed BODY_SKATE_START); riya touched the parabola — fires the slope fx burst."
        @tier "domain"
      SECANT_PICKED -> external {
        id : string!
        kind : string!
        x : number!
        y : number!
        glyph : string
        message : string
      }
        @description "A pickup was collected (renamed PICKED from std-pickup); the play trait bursts the pickup glyph, the challenge trait applies kind-conditional effects."
        @tier "domain"
      SECANT_COLLECT -> external {
        total : number!
      }
        @description "Running pickup count (renamed COLLECT from std-pickup); updates score/objectives and forwards to the objective-flow gate."
        @tier "domain"
      SECANT_PICKUP_SET_COMPLETED -> external {
      }
        @description "Every pickup in the set is collected (renamed PICKUP_SET_COMPLETED from std-pickup)."
        @tier "domain"
      SECANT_RESTART -> external {
        id : string
      }
        @description "Reseed broadcast consumed by this world's platformer-body/objective-flow authorities (renamed RESTART)."
        @tier "domain"
      SECANT_BURST -> external {
        particles : [RiyaSecantFx]
      }
        @description "Particle batch spawned on star pickup, pit respawn, or tutorial dismiss; fx-particles fades it."
        @tier "domain"
      SECANT_PROGRESS -> external {
        objectivesLeft : number!
        movesLeft : number!
      }
        @description "Sparse progress signal emitted when a star is collected; the objective-flow gate resolves won from it."
        @tier "domain"
      SECANT_GAME_END -> external {
        result : string!
      }
        @description "Win-gate resolution from this world's objective-flow authority (renamed GAME_END); won clears the level."
        @tier "domain"
      RIYA_LEVEL_SOLVED -> external {
        level : string
      }
        @description "Every ★ captured — the win gate resolved won (guarded by celebrated so the gate's repeated GAME_ENDs fire it once)."
        @tier "domain"
      SECANT_SET_PLATFORMS -> external {
        platforms : [RiyaSecantPlatform]!
      }
        @description "Renamed SET_PLATFORMS consumed by this world's platformer-body authority; forwards the canonical RIYA_LEVEL_DATA terrain to collision."
        @tier "domain"
      SECANT_SET_SKATE_CURVE -> external {
        curve : [RiyaSecantCurveSample]!
      }
        @description "Renamed SET_SKATE_CURVE consumed by this world's platformer-body authority; forwards the canonical RIYA_LEVEL_DATA skate surface."
        @tier "domain"
      SECANT_SET_FEATURES -> external {
        features : [RiyaSecantPickup]!
      }
        @description "Renamed SET_FEATURES consumed by this world's pickup authority; forwards the canonical RIYA_LEVEL_DATA stars."
        @tier "domain"
    }

    listens {
      SECANT_TUTORIAL_DONE { id : string }
      RIYA_LEVEL_DATA {
        id : string!
        name : string!
        equation : string!
        concept : string!
        regionColor : string!
        entryY : number!
        exitY : number!
        platforms : [RiyaSecantPlatform]!
        stars : [RiyaSecantPickup]!
        curveOverlay : [RiyaSecantCurve]
        skateCurve : [RiyaSecantCurveSample]
      }
    }

    config {
      ghostCurve : RiyaSecantCurve = { label: "", color: "#94a3b8", dash: "dashed", samples: [ { x: -8, y: 4 }, { x: -7, y: 3.06 }, { x: -6, y: 2.25 }, { x: -5, y: 1.56 }, { x: -4, y: 1 }, { x: -3, y: 0.56 }, { x: -2, y: 0.25 }, { x: -1, y: 0.06 }, { x: 0, y: 0 }, { x: 1, y: 0.06 }, { x: 2, y: 0.25 }, { x: 3, y: 0.56 }, { x: 4, y: 1 }, { x: 5, y: 1.56 }, { x: 6, y: 2.25 }, { x: 7, y: 3.06 }, { x: 8, y: 4 } ] }
        @label "Ghost Curve"
        @description "A dashed ghost of the base parabola for before/after contrast."
        @tier "presentation"
      tangentCurve : RiyaSecantCurve = { label: "tangent", color: "#38bdf8", samples: [ { x: 3, y: 0.3125 }, { x: 3.5, y: 0.625 }, { x: 4, y: 0.9375 }, { x: 4.5, y: 1.25 }, { x: 5, y: 1.5625 }, { x: 5.5, y: 1.875 }, { x: 6, y: 2.1875 }, { x: 6.5, y: 2.5 }, { x: 7, y: 2.8125 } ] }
        @label "Tangent Curve"
        @description "The tangent line at the beacon point x = 5, slope = 5/8. Riya rides it once the secant morph completes."
        @tier "presentation"
      beaconTargetX : number = 5
        @label "Beacon Target X"
        @description "The fixed x where the secant becomes the tangent (and where the final star sits)."
        @tier "domain"
      beaconStartX : number = 7.5
        @label "Beacon Start X"
        @description "The beacon's initial x when Riya is far left; it slides toward beaconTargetX as she approaches."
        @tier "domain"
      beaconSlideStartX : number = -6
        @label "Beacon Slide Start X"
        @description "Riya x at which the beacon begins sliding from beaconStartX toward beaconTargetX."
        @tier "domain"
      beaconSlideEndX : number = 3
        @label "Beacon Slide End X"
        @description "Riya x at which the beacon reaches beaconTargetX and the secant becomes the tangent."
        @tier "domain"
      equationText : string = "y = x²/16"
        @label "Equation Text"
        @description "Equation of this world's curve, shown by the skate fx burst."
        @tier "presentation"
      equationColor : string = "#7dd3fc"
        @label "Equation Color"
        @description "Color of the floating slope label that follows riya while she skates."
        @tier "presentation"
