        @label "Respawn X"
        @description "X riya teleports to after a pit fall (matches SecantBody spawn.x)."
        @tier "domain"
      respawnY : number = 2.65
        @label "Respawn Y"
        @description "Y riya teleports to after a pit fall (matches SecantBody spawn.y)."
        @tier "domain"
      objectiveText : string = ""
        @label "Objective Text"
        @description "HUD objective chip intentionally empty; the secant/tangent geometry carries the objective."
        @tier "presentation"
      worldName : string = "The Secant"
        @label "World Name"
        @description "This world's display name, shown in the game-shell title chip as \"riya · <worldName>\"."
        @tier "presentation"
      showTelemetry : boolean = false
        @label "Show Telemetry"
        @description "When true, draws a compact x/y/v readout on the canvas near riya (debug aid only). Off keeps the HUD to score only."
        @tier "domain"
      arrowOffsetY : number = 1.9
        @label "Arrow Offset Y"
        @description "World units above the body center where the velocity vector arrow originates, so it floats above the player sprite."
        @tier "presentation"
      arrowScale : number = 0.5
        @label "Arrow Scale"
        @description "Scale factor for the velocity vector arrow."
        @tier "presentation"
      fxPresets : [RiyaSecantFxPreset] = [ { type: "info", color: "#38bdf8", color2: "#0c4a6e", size: 0.8, shape: "puff", count: 4 }, { type: "pickup", color: "#ffe066", color2: "#ffffff", size: 1.0, shape: "spark", count: 5, glow: 0.12, vy: -0.1 }, { type: "narrative", color: "#38bdf8", size: 1.4, shape: "ring", count: 1, glow: 0.1 } ]
        @label "Fx Presets"
        @description "Look table for world-space particle effects rendered by the draw-fx-layer."
        @tier "presentation"
      conceptText : string = "The secant slope between two points on a curve approaches the tangent slope as the points merge — average rate becomes instantaneous rate."
