    }
  }

  trait SecantChallenge -> @rebindable RiyaSecantState [game-core, instance] {
    initial: idle

    state idle {
      SECANT_PICKED -> idle when (and (== @entity.zoneId @config.zoneId) (== @entity.active true))
        (if (== @payload.kind "tuning")
          (emit SECANT_BURST { particles: (array/map [ "tuning" ] (fn _ { id: "narrative-tuning", type: "narrative", x: @payload.x, z: (+ @payload.y 1.2), y: 0, message: "Δx → 0", ttl: 2, maxTtl: 2, bornAt: (time/now), space: "world", effect: "float-text", color: "#f472b6", size: 0.7, vx: 0, vy: 0, vz: 0, particleCount: 1 })) })
          null)
    }

    emits {
      SECANT_BURST -> external {
        particles : [RiyaSecantFx]
      }
        @description "Particle batch spawned on the Δx → 0 tuning-pad narrative beat; fx-particles fades it."
        @tier "domain"
    }

    listens {
      SECANT_PICKED { id : string!, kind : string!, x : number!, y : number!, glyph : string, message : string }
    }

    config {
      zoneId : string = "secant"
        @label "Zone Id"
        @description "The zone this challenge choreography belongs to. Guards compare it against @entity.zoneId, so a composed open world fires it only while riya stands in this zone; standalone the entity default equals this knob and the guard is always true."
        @tier "domain"
    }
  }

  trait RiyaSecantClear -> @rebindable RiyaSecantState [interaction, instance] {
    initial: watching

    state watching {
      INIT -> watching
        (render-ui overlay null)

      RIYA_LEVEL_SOLVED -> watching
        (render-ui overlay {
          type: game-menu
          title: @config.clearTitle
          subtitle: @config.clearSubtitle
          options: [ { id: "next", label: "Next ▶", event: "SECANT_NEXT", variant: "primary" } ]
        })

      SECANT_NEXT -> watching
        (render-ui overlay null)
        (navigate @config.nextPath)

      CLOSE -> watching
        (render-ui overlay null)
    }

    listens {
      RIYA_LEVEL_SOLVED { level : string }
      SECANT_NEXT { id : string }
      CLOSE
    }

    config {
      nextPath : string = "/riya-secant"
        @label "Next Path"
        @description "Page the clear overlay's Next button navigates to. Standalone default replays this world; riya-game-platformer overrides it with the next world's path."
        @tier "presentation"
      clearTitle : string = "Secant clear ★"
        @label "Clear Title"
        @description "Overlay title once every star is collected."
        @tier "presentation"
      clearSubtitle : string = "Average rate → instantaneous rate: the secant melts into the tangent."
        @label "Clear Subtitle"
        @description "One-line celebration under the clear title."
        @tier "presentation"
    }
  }

  page "/riya-secant" as RiyaSecantPage -> SecantLevelData, SecantBody, SecantGate, SecantFx, SecantPickup, SecantTutorial, RiyaSecantGenre, RiyaSecantPlay, SecantChallenge, RiyaSecantClear
}
